package com.alan.thormonitor.tests;
import android.app.*;import android.content.*;import android.content.res.Configuration;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import java.lang.reflect.*;import java.util.*;import java.io.*;
public class HostSetupRenderTest extends Instrumentation {
 Activity a;Context target,base;SharedPreferences actual;Configuration original;Field baseField;Throwable failure;String[] theme={"clearPurple"};boolean restored;
 public void onCreate(Bundle b){super.onCreate(b);start();}
 Field member(Class<?> c,String name)throws Exception{Field f=c.getDeclaredField(name);f.setAccessible(true);return f;}
 void set(String name,Object value)throws Exception{member(a.getClass(),name).set(a,value);}
 void build()throws Exception{Method m=a.getClass().getDeclaredMethod("build");m.setAccessible(true);m.invoke(a);}
 void ui(Runnable r){runOnMainSync(()->{try{r.run();}catch(Throwable e){failure=e;}});if(failure!=null)throw new RuntimeException(failure);}
 SharedPreferences proxy(){final SharedPreferences.Editor[] editor={null};editor[0]=(SharedPreferences.Editor)Proxy.newProxyInstance(SharedPreferences.Editor.class.getClassLoader(),new Class[]{SharedPreferences.Editor.class},(p,m,args)->m.getName().equals("apply")?null:m.getName().equals("commit")?true:editor[0]);return (SharedPreferences)Proxy.newProxyInstance(SharedPreferences.class.getClassLoader(),new Class[]{SharedPreferences.class},(p,m,args)->m.getName().equals("edit")?editor[0]:m.getName().equals("getString")&&args[0].equals("appearance")?theme[0]:m.getName().equals("getBoolean")&&args[0].equals("setup_complete")?false:m.invoke(actual,args));}
 void screenshot(String filename,View v,int width)throws Exception{v.animate().cancel();v.setAlpha(1);v.setTranslationX(0);v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));v.layout(0,0,width,v.getMeasuredHeight());check(v);Bitmap b=Bitmap.createBitmap(width,v.getMeasuredHeight(),Bitmap.Config.ARGB_8888);Canvas canvas=new Canvas(b);canvas.drawColor(a.getWindow().getStatusBarColor());v.draw(canvas);try(FileOutputStream f=new FileOutputStream(new File(target.getCacheDir(),filename))){b.compress(Bitmap.CompressFormat.PNG,100,f);}b.recycle();}
 void check(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(t.getLayout()!=null)for(int i=0;i<t.getLineCount();i++)if(t.getLayout().getLineMax(i)>t.getWidth()-t.getTotalPaddingLeft()-t.getTotalPaddingRight()+3)throw new AssertionError("Text clipped: "+t.getText());}if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)check(g.getChildAt(i));}}
 boolean hasText(View v,String text){if(v instanceof TextView&&((TextView)v).getText().toString().equals(text))return true;if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)if(hasText(g.getChildAt(i),text))return true;}return false;}
 public void onStart(){Bundle out=new Bundle();try{
  target=getTargetContext();a=startActivitySync(new Intent().setClassName(target,"com.alan.thormonitor.MainActivity").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));base=a.getBaseContext();actual=a.getSharedPreferences("monitor",0);original=new Configuration(a.getResources().getConfiguration());baseField=member(ContextWrapper.class,"mBase");final SharedPreferences fake=proxy();
  ui(()->{try{baseField.set(a,new ContextWrapper(base){public SharedPreferences getSharedPreferences(String name,int mode){return name.equals("monitor")?fake:super.getSharedPreferences(name,mode);}});set("prefs",fake);}catch(Exception e){throw new RuntimeException(e);}});
  for(String style:new String[]{"light","dark","clearPurple","rainbow"}){theme[0]=style;for(int step=0;step<6;step++){final int index=step;ui(()->{try{Configuration config=new Configuration(original);config.fontScale=1;a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());set("screen",1);set("step",index);set("renderedSetupStep",-1);build();View page=(View)member(a.getClass(),"page").get(a);screenshot("setup-"+style+"-"+index+".png",page,Math.round(620*a.getResources().getDisplayMetrics().density));if(!hasText(page,(index+1)+" of 6"))throw new AssertionError("Missing progress");}catch(Exception e){throw new RuntimeException(e);}});}}
  theme[0]="clearPurple";for(int step=0;step<6;step++){final int index=step;ui(()->{try{Configuration config=new Configuration(original);config.fontScale=1.8f;a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());set("screen",1);set("step",index);set("renderedSetupStep",-1);build();screenshot("setup-large-"+index+".png",(View)member(a.getClass(),"page").get(a),Math.round(340*a.getResources().getDisplayMetrics().density));}catch(Exception e){throw new RuntimeException(e);}});}
  ui(()->{try{Configuration config=new Configuration(original);a.getResources().updateConfiguration(config,a.getResources().getDisplayMetrics());for(int screen:new int[]{2,3,5}){set("screen",screen);build();screenshot("settings-"+screen+".png",(View)member(a.getClass(),"page").get(a),Math.round(620*a.getResources().getDisplayMetrics().density));}}catch(Exception e){throw new RuntimeException(e);}});
  out.putString("render","six steps in all four themes, 1.8x text at narrow width, settings and recovery passed");out.putString("preferences","render fixtures did not save permissions, pairing, theme or settings");out.putString("status","passed");
 }catch(Throwable e){out.putString("error",e.toString());}finally{if(a!=null&&baseField!=null)try{runOnMainSync(()->{try{baseField.set(a,base);set("prefs",actual);a.getResources().updateConfiguration(original,a.getResources().getDisplayMetrics());set("screen",0);set("step",0);set("renderedSetupStep",-1);build();restored=true;}catch(Exception ignored){}});}catch(Throwable ignored){}}finish(out.containsKey("error")?1:0,out);}
}
